 * Phase-1 (syntax) parsing of a single directive line: turns raw text into
 * an AST without touching any document state. Semantic resolution against
 * the document tree happens later, in materialize.js.
 */
import { DocError } from './errors.js'

const BARE_CHAR = /[A-Za-z0-9_-]/
const HEX_CHAR = /[0-9a-fA-F]/
const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Cursor {
  constructor(text, lineNo, pos = 0) {
    this.text = text
    this.lineNo = lineNo
    this.pos = pos
  }

  peek() {
    return this.pos < this.text.length ? this.text[this.pos] : undefined
  }
}

function fail(cur, reason) {
  throw new DocError(cur.lineNo, reason)
}

function skipWS(cur) {
  while (cur.peek() === ' ' || cur.peek() === '\t') cur.pos++
}

function parseBasicStringRaw(cur) {
  cur.pos++ // consume opening "
  let out = ''
  for (;;) {
    const ch = cur.peek()
    if (ch === undefined) fail(cur, 'unterminated string')
    if (ch === '"') {
      cur.pos++
      return out
    }
    if (ch === '\\') {
      cur.pos++
      const esc = cur.peek()
      if (esc === undefined) fail(cur, 'unterminated string')
      switch (esc) {
        case '"':
          out += '"'
          cur.pos++
          break
        case '\\':
          out += '\\'
          cur.pos++
          break
        case 'n':
          out += '\n'
          cur.pos++
          break
        case 't':
          out += '\t'
          cur.pos++
          break
        case 'r':
          out += '\r'
          cur.pos++
          break
        case '0':
          out += '\0'
          cur.pos++
          break
        case 'u': {
          cur.pos++
          let hex = ''
          for (let k = 0; k < 4; k++) {
            const hc = cur.peek()
            if (hc === undefined) fail(cur, 'unterminated string')
            if (!HEX_CHAR.test(hc)) fail(cur, 'invalid escape \\u')
            hex += hc
            cur.pos++
          }
          out += String.fromCharCode(parseInt(hex, 16))
          break
        }
        default:
          fail(cur, `invalid escape \\${esc}`)
      }
    } else {
      out += ch
      cur.pos++
    }
  }
}

function parseLiteralStringRaw(cur) {
  cur.pos++ // consume opening '
  const start = cur.pos
  for (;;) {
    const ch = cur.peek()
    if (ch === undefined) fail(cur, 'unterminated string')
    if (ch === "'") {
      const out = cur.text.slice(start, cur.pos)
      cur.pos++
      return out
    }
    cur.pos++
  }
}

function parseNameSyntax(cur) {
  const ch = cur.peek()
  if (ch === '"') return parseBasicStringRaw(cur)
  if (ch === "'") return parseLiteralStringRaw(cur)
  if (ch !== undefined && BARE_CHAR.test(ch)) {
    const start = cur.pos
    while (cur.peek() !== undefined && BARE_CHAR.test(cur.peek())) cur.pos++
    return cur.text.slice(start, cur.pos)
  }
  fail(cur, 'expected a name')
}

function parseDottedNameSyntax(cur) {
  skipWS(cur)
  const parts = [parseNameSyntax(cur)]
  skipWS(cur)
  while (cur.peek() === '.') {
    cur.pos++
    skipWS(cur)
    parts.push(parseNameSyntax(cur))
    skipWS(cur)
  }
  return parts
}

function classifyNumber(token) {
  if (INT_RE.test(token)) {
    return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  }
  if (FLOAT_RE.test(token) && (token.includes('.') || /[eE]/.test(token))) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  return null
}

function parseValueSyntax(cur) {
  skipWS(cur)
  const ch = cur.peek()
  if (ch === undefined || ch === ',' || ch === ']' || ch === '}') {
    fail(cur, 'expected a value')
  }
  if (ch === '"') return { kind: 'string', value: parseBasicStringRaw(cur) }
  if (ch === "'") return { kind: 'string', value: parseLiteralStringRaw(cur) }
  if (ch === '[') return parseArraySyntax(cur)
  if (ch === '{') return parseInlineTableSyntax(cur)

  const start = cur.pos
  while (cur.peek() !== undefined && !' \t,]}'.includes(cur.peek())) cur.pos++
  const token = cur.text.slice(start, cur.pos)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  const num = classifyNumber(token)
  if (num) return num
  fail(cur, `invalid value ${token}`)
}

function parseArraySyntax(cur) {
  cur.pos++ // consume [
  skipWS(cur)
  const items = []
  if (cur.peek() === ']') {
    cur.pos++
    return { kind: 'array', items }
  }
  for (;;) {
    skipWS(cur)
    items.push(parseValueSyntax(cur))
    skipWS(cur)
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      skipWS(cur)
      if (cur.peek() === ']') {
        cur.pos++
        break
      }
      continue
    }
    if (c === ']') {
      cur.pos++
      break
    }
    fail(cur, 'unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTableSyntax(cur) {
  cur.pos++ // consume {
  skipWS(cur)
  const pairs = []
  if (cur.peek() === '}') {
    cur.pos++
    return { kind: 'inlinetable', pairs }
  }
  for (;;) {
    skipWS(cur)
    const names = parseDottedNameSyntax(cur)
    skipWS(cur)
    if (cur.peek() !== '=') fail(cur, 'expected = in an inline table')
    cur.pos++
    skipWS(cur)
    const value = parseValueSyntax(cur)
    pairs.push({ names, value })
    skipWS(cur)
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      continue
    }
    if (c === '}') {
      cur.pos++
      break
    }
    fail(cur, 'unterminated inline table')
  }
  return { kind: 'inlinetable', pairs }
}

function trailingCheck(cur, reason) {
  skipWS(cur)
  const c = cur.peek()
  if (c === undefined) return
  if (c === '#' || c === ';') return
  fail(cur, reason)
}

function parseHeaderLine(cur) {
  cur.pos++ // consume first [
  let isArray = false
  if (cur.peek() === '[') {
    isArray = true
    cur.pos++
  }
  skipWS(cur)
  const names = parseDottedNameSyntax(cur)
  skipWS(cur)
  if (cur.peek() !== ']') fail(cur, 'unterminated table header')
  cur.pos++
  if (isArray) {
    if (cur.peek() !== ']') fail(cur, 'unterminated table header')
    cur.pos++
  }
  trailingCheck(cur, 'trailing text after a table header')
  return { type: isArray ? 'headerArray' : 'header', names }
}

function parseAssignmentLine(cur) {
  const names = parseDottedNameSyntax(cur)
  skipWS(cur)
  if (cur.peek() !== '=') fail(cur, 'expected key = value')
  cur.pos++
  skipWS(cur)
  const value = parseValueSyntax(cur)
  trailingCheck(cur, 'trailing text after a value')
  return { type: 'assignment', names, value }
}

/**
 * Parses one raw source line. Returns null for a line that contributes
 * nothing (blank, or comment-only), otherwise an AST node tagged with the
 * line number it came from.
 */
export function parseLine(raw, lineNo) {
  let i = 0
  while (i < raw.length && (raw[i] === ' ' || raw[i] === '\t')) i++
  if (i >= raw.length) return null
  if (raw[i] === '#' || raw[i] === ';') return null

  const cur = new Cursor(raw, lineNo, i)
  const ast = raw[i] === '[' ? parseHeaderLine(cur) : parseAssignmentLine(cur)
  ast.lineNo = lineNo
  return ast
}
"}

