import { DocError } from './errors.js'

export function makeTable() {
  return { kind: 'table', entries: new Map(), headerDefined: false }
}

/**
 * Walks all but the last segment of a dotted name from `container`,
 * creating intermediate tables as needed and following an array of tables
 * to its last element. Returns the table the final segment lives in, and
 * the root-counted path leading to it.
 */
function walkIntermediateSegments(container, names, basePath, lineNo) {
  let node = container
  const path = basePath.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path.push(name)
    let entry = node.entries.get(name)
    if (entry === undefined) {
      entry = makeTable()
      node.entries.set(name, entry)
    }
    if (entry.kind === 'array-of-tables') {
      entry = entry.items[entry.items.length - 1]
    } else if (entry.kind !== 'table') {
      throw new DocError(lineNo, `${path.join('.')} is not a table`)
    }
    node = entry
  }
  return { node, path }
}

