  if (ast.kind === 'array') {
    return { kind: 'array', items: ast.items.map((it) => materializeValue(it, path, lineNo)) }
  }
  if (ast.kind === 'inlinetable') {
    const table = makeTable()
    for (const pair of ast.pairs) {
      materializeAssignment(table, path, pair.names, pair.value, lineNo)
    }
    return table
  }
  return ast // scalar node: already {kind, value}
