  const { node, path } = walkIntermediateSegments(container, names, basePath, lineNo)
  const finalName = names[names.length - 1]
  const fullPath = path.concat(finalName)
  if (node.entries.has(finalName)) {
    throw new DocError(lineNo, `key ${fullPath.join('.')} is defined twice`)
  }
  const value = materializeValue(valueAst, fullPath, lineNo)
  node.entries.set(finalName, value)
