      current = table
      currentPath = path
    } else if (ast.type === 'headerArray') {
      const { table, path } = materializeHeaderArray(root, ast.names, lineNo)
      current = table
      currentPath = path
    } else {
      materializeAssignment(current, currentPath, ast.names, ast.value, lineNo)
    }
  }

  return root
}
