{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-1Vc82q/src/format.js","content":"/** Renders a document tree as canonical JSON, or as a flat key/type listing. */

/** Compares strings in ascending order by Unicode code point. */
function compareByCodePoint(a, b) {
  const ac = [...a]
  const bc = [...b]
  const len = Math.min(ac.length, bc.length)
  for (let i = 0; i < len; i++) {
    const diff = ac[i].codePointAt(0) - bc[i].codePointAt(0)
    if (diff !== 0) return diff
  }
  return ac.length - bc.length
}

function sortedKeys(table) {
  return [...table.entries.keys()].sort(compareByCodePoint)
}

function formatJSONNode(node, depth) {
  const pad = '  '.repeat(depth)
  const padInner = '  '.repeat(depth + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (key) => `${padInner}${JSON.stringify(key)}: ${formatJSONNode(node.entries.get(key), depth + 1)}`
      )
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'array':
    case 'array-of-tables': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((item) => `${padInner}${formatJSONNode(item, depth + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    default:
      return JSON.stringify(node.value)
  }
}

export function formatJSON(root) {
  return `${formatJSONNode(root, 0)}\n`
}

function typeName(node) {
  if (node.kind === 'array-of-tables') return 'array'
  return node.kind
}

export function formatKeys(root) {
  const lines = []
  function walk(node, path) {
    if (node.kind === 'table') {
      for (const key of sortedKeys(node)) {
        const child = node.entries.get(key)
        const childPath = path === '' ? key : `${path}.${key}`
        lines.push(`${childPath} ${typeName(child)}`)
        walk(child, childPath)
      }
    } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
      node.items.forEach((item, i) => {
        const childPath = `${path}[${i}]`
        lines.push(`${childPath} ${typeName(item)}`)
        walk(item, childPath)
      })
    }
  }
  walk(root, '')
  return lines.map((line) => `${line}\n`).join('')
}
"}

